// currently only used in this module and tests
const CEDAR_COLORS = {
  black: [46, 46, 46, 255],
  blue: [0, 122, 194, 255],
  gray: [128, 128, 128, 200],
  red: [255, 0, 0, 200],
  white: [255, 255, 255, 255]
};
const applyBarChartFormatting = (model) => {
  model.setSeriesColor(CEDAR_COLORS.blue, 0);
};
const applyLineChartFormatting = (model) => {
  model.setSeriesLineColor(CEDAR_COLORS.blue, 0);
  model.setSeriesLineWidth(1, 0);
  model.setSeriesMarkerColor(CEDAR_COLORS.blue, 0);
  model.setSeriesMarkerSize(5, 0);
};
// apply cedar formatting to model and return the config, see:
// https://github.com/ArcGIS/opendata-ui/blob/3e51721aa365c9b7299a78973f4762c8062eed32/packages/hub-components/src/utils/cedar/index.ts
const getCedarFormattedConfig = (model, options) => {
  const _options = options || {};
  const { isSparkline = false } = _options;
  const textSymbolBase = {
    type: "esriTS",
    color: CEDAR_COLORS.black,
  };
  const chartType = model.getChartType();
  // colors
  model.setColorMatch(false);
  if (chartType === 'barSeries') {
    applyBarChartFormatting(model);
  }
  else {
    applyLineChartFormatting(model);
  }
  // title
  model.setTitleSymbol(Object.assign(Object.assign({}, textSymbolBase), { font: {
      size: 20
    } }));
  // axes
  if (isSparkline) {
    model.setXAxisTitleVisibility(false);
    model.setYAxisTitleVisibility(false);
    // NOTE: axis line and label visibility are set below on the config
  }
  else {
    model.setAxisLabelsSymbol(Object.assign(Object.assign({}, textSymbolBase), { font: {
        size: 14
      } }));
    model.setAxisLinesSymbol({
      type: "esriSLS",
      color: CEDAR_COLORS.gray,
      width: 2
    });
  }
  // formatting that must be applied directly to the config instead of the model
  // NOTE: Nels says we can use model.setConfig() if we have to return the model instead
  const config = model.getConfig();
  config.cursorCrosshair = {
    type: "cursorCrosshair",
    style: {
      type: "esriSLS",
      style: "esriSLSDash",
      color: CEDAR_COLORS.red,
      width: 1,
    },
    horizontalLineVisible: true,
    verticalLineVisible: true,
  };
  if (isSparkline) {
    config.axes.forEach(axis => {
      axis.visible = false;
      axis.labels.visible = false;
    });
  }
  return config;
};

// create a layer definition from telemetry data
// and set up the model
const setupTelemetryChartModel = async (model, dataItems) => {
  // create a feature layer
  // NOTE: we handle no data higher up in the call stack
  const [categoryField, numericField] = Object.keys(dataItems[0]);
  const categoryType = "date";
  const numericFields = [numericField];
  const inlineData = { dataItems };
  const iLayer = wm({ categoryField, categoryType, numericFields, inlineData });
  // set up the model
  await model.setup({ iLayer });
  // set fields
  await (model.setCategory
    ? model.setCategory(categoryField)
    : model.setXAxisField(categoryField));
  await model.setNumericFields(numericFields);
  // the telemetry API already bins the data
  // so we do not want the chart to aggregate it again
  await model.setAggregationType('no_aggregation');
};
const formatTelemetryChartModel = (model, timeLabel, dataLabel, timeIntervalUnits = 'esriTimeUnitsDays') => {
  // NOTE: we render the title in the parent component
  // so we don't want the show the chart component's default title
  model.setChartTitleVisibility(false);
  // time interval
  model.setTimeIntervalUnits(timeIntervalUnits);
  model.setTimeIntervalSize(1);
  // configure axes titles and formatting
  model.setXAxisTitleText(timeLabel);
  model.setYAxisTitleText(dataLabel);
  // NOTE: this controls the label in the tooltip
  model.setSeriesName(dataLabel, 0);
  const numericField = model.getNumericFields()[0];
  const maximumFractionDigits = numericField === 'session-activity:average'
    ? 1
    : 0;
  model.setYAxisValueFormat({
    type: "number",
    intlOptions: {
      style: "decimal",
      notation: "compact",
      minimumFractionDigits: 0,
      maximumFractionDigits
    }
  });
};
